"""Source-free frame perception helpers for cracking.

This module is deliberately observational: it derives compact symbolic state
from `env.frame()` and `env.clone()` only. It is a cofibration-style scaffold:
raw pixels are embedded into a monotone tower of reusable observations
(components -> objects -> action deltas -> replay states). Candidate level
logic should be written against these quotients, then replay-validated by the
harness. No game source or prior solution history is read here.
"""
from collections import deque
from dataclasses import dataclass
from typing import Dict, Iterable, List, Optional, Sequence, Tuple

import numpy as np

UP, DOWN, LEFT, RIGHT, USE = 1, 2, 3, 4, 5
ACTIONS = (UP, DOWN, LEFT, RIGHT, USE)
DIRS = {UP: (-1, 0), DOWN: (1, 0), LEFT: (0, -1), RIGHT: (0, 1)}
ACTION_NAME = {UP: "UP", DOWN: "DOWN", LEFT: "LEFT", RIGHT: "RIGHT", USE: "USE"}


@dataclass(frozen=True)
class Blob:
    color: int
    bbox: Tuple[int, int, int, int]  # r0, c0, r1, c1 inclusive
    area: int
    centroid: Tuple[float, float]

    @property
    def top_left(self):
        return self.bbox[0], self.bbox[1]

    @property
    def size(self):
        r0, c0, r1, c1 = self.bbox
        return r1 - r0 + 1, c1 - c0 + 1


def arr(frame) -> np.ndarray:
    return np.asarray(frame)


def color_counts(frame) -> Dict[int, int]:
    vals, cnts = np.unique(arr(frame), return_counts=True)
    return {int(v): int(c) for v, c in zip(vals, cnts)}


def connected_components(frame, colors: Optional[Iterable[int]] = None,
                         min_area: int = 1) -> List[Blob]:
    f = arr(frame)
    wanted = None if colors is None else {int(c) for c in colors}
    seen = np.zeros(f.shape, dtype=bool)
    out: List[Blob] = []
    rows, cols = f.shape[:2]
    for r in range(rows):
        for c in range(cols):
            if seen[r, c]:
                continue
            color = int(f[r, c])
            if wanted is not None and color not in wanted:
                seen[r, c] = True
                continue
            q = [(r, c)]
            seen[r, c] = True
            pts = []
            while q:
                x, y = q.pop()
                pts.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < rows and 0 <= ny < cols and not seen[nx, ny] and int(f[nx, ny]) == color:
                        seen[nx, ny] = True
                        q.append((nx, ny))
            if len(pts) >= min_area:
                rs = [p[0] for p in pts]
                cs = [p[1] for p in pts]
                out.append(Blob(color, (min(rs), min(cs), max(rs), max(cs)),
                                len(pts), (sum(rs) / len(pts), sum(cs) / len(pts))))
    return sorted(out, key=lambda b: (b.color, b.bbox))


def block_signatures(frame, cell: int = 4) -> Dict[Tuple[int, int], Tuple[int, ...]]:
    """Partition a frame into fixed cells and return each cell's color signature."""
    f = arr(frame)
    out = {}
    for r in range(0, f.shape[0], cell):
        for c in range(0, f.shape[1], cell):
            out[(r // cell, c // cell)] = tuple(int(v) for v in sorted(np.unique(f[r:r+cell, c:c+cell])))
    return out

def merge_preserving_mass(env, colors=(10, 6, 15, 11), hazard_color=7,
                          goal_color=9, beam_width=12, max_depth=45,
                          target_color=None):
    """Merge equal markers while avoiding losses caused by moving hazards.

    Marker colors encode successive doublings. Search short coordinate pulls
    on clones, reject any loss of total mass, and favor fewer markers and
    shorter distances between equal pairs. Commit after merging to one marker
    or producing the requested target color while preserving total mass.
    """
    import math
    import time

    weights = {color: 2 ** i for i, color in enumerate(colors)}

    def markers(world):
        return [b for b in connected_components(world.frame(), colors=colors)
                if b.bbox[0] >= 10]

    def points(blobs):
        return [(b.color, b.bbox[3], b.bbox[2]) for b in blobs]

    goals = connected_components(env.frame(), colors=[goal_color], min_area=4)
    if not goals:
        return
    gy, gx = max(goals, key=lambda b: b.area).centroid

    def score(blobs):
        positions = points(blobs)
        distance = 0
        for color in colors:
            group = [(x, y) for c, x, y in positions if c == color]
            while len(group) > 1:
                d, i, j = min((math.dist(a, b), i, j)
                              for i, a in enumerate(group)
                              for j, b in enumerate(group) if j > i)
                distance += d
                group.pop(j)
                group.pop(i)
        return (len(blobs) * 100 + distance + .2 * sum(
            math.dist((x, y), (gx, gy)) * weights[c] / total
            for c, x, y in positions))

    trial = env.clone()
    total = sum(weights[b.color] for b in markers(trial))
    if not total:
        return
    beam = [(score(markers(trial)), trial, [])]
    seen = set()
    started = time.monotonic()
    probes = 0
    for _ in range(max_depth):
        successors = []
        for _, world, path in beam:
            positions = points(markers(world))
            actions = set()
            for c, x, y in positions:
                for dx, dy in [(0, 0), (6, 0), (-6, 0), (0, 6), (0, -6),
                               (4, 4), (-4, 4), (4, -4), (-4, -4)]:
                    if 1 <= x + dx <= 62 and 11 <= y + dy <= 61:
                        actions.add((6, x + dx, y + dy))
            for i, (c, x, y) in enumerate(positions):
                for other, tx, ty in positions[i + 1:]:
                    if c == other and math.dist((x, y), (tx, ty)) <= 18:
                        actions.add((6, round((x + tx) / 2),
                                     round((y + ty) / 2)))
            for action in sorted(actions):
                child = world.clone()
                safe_step(child, action)
                probes += 1
                if probes % 100 == 0:
                    delay = probes / 250 - (time.monotonic() - started)
                    if delay > 0:
                        time.sleep(delay)
                blobs = markers(child)
                if sum(weights[b.color] for b in blobs) != total:
                    continue
                hazard = tuple(b.bbox for b in connected_components(
                    child.frame(), colors=[hazard_color]))
                key = (tuple(points(blobs)), hazard)
                if key in seen:
                    continue
                seen.add(key)
                next_path = path + [action]
                if (len(blobs) == 1 or
                        target_color is not None and any(
                            b.color == target_color for b in blobs)):
                    for step in next_path:
                        safe_step(env, step)
                    return
                successors.append((score(blobs), child, next_path))
        successors.sort(key=lambda item: item[0])
        beam = successors[:beam_width]
        if not beam:
            return
